@import "tailwindcss";

@theme {
  --font-sans: 'Inter', ui-sans-serif, system-ui, sans-serif;
  --font-display: 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif;

  --color-sf-black: #000000;
  --color-sf-purple: #7638FA;
  --color-sf-orange: #FF7A00;
  --color-sf-pink: #E91E8C;
  --color-sf-cream: #F6F5F2;
  --color-sf-muted: #6B6B6B;
  --color-sf-border: #E5E5E5;
  --color-sf-surface: #FFFFFF;
  --color-sf-safety: #F0FDF4;
  --color-sf-creators: #FDF4FF;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: #111111;
  background: #ffffff;
}

/* Hide scrollbar for news carousel but keep functionality */
.hide-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.hide-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Gradient text utility */
.gradient-text {
  background: linear-gradient(135deg, #7638FA 0%, #E91E8C 50%, #FF7A00 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Hero gradient background */
.hero-gradient {
  background: linear-gradient(135deg, #faf5ff 0%, #fff7ed 40%, #fdf2f8 100%);
}

/* Tag pill styles */
.tag-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Smooth card hover */
.card-hover {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.card-hover:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 40px -12px rgba(0,0,0,0.12);
}

/* Button press */
.btn-press {
  transition: transform 0.1s ease;
}
.btn-press:active {
  transform: scale(0.97);
}

/* Focus ring */
.focus-ring:focus-visible {
  outline: 2px solid #7638FA;
  outline-offset: 2px;
}

/* Mobile menu overlay */
.mobile-menu {
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.mobile-menu.open {
  transform: translateX(0);
}

/* News card width */
.news-card {
  min-width: 300px;
  max-width: 340px;
  flex: 0 0 auto;
}

@media (max-width: 640px) {
  .news-card {
    min-width: 260px;
    max-width: 280px;
  }
}

